<template><div><div class="page-head"><h2>角色管理</h2><el-button type="primary" @click="open()">新增角色</el-button></div><el-table :data="items" border><el-table-column prop="name" label="名称"/><el-table-column prop="description" label="说明"/><el-table-column label="权限"><template #default="s"><el-tag v-for="p in s.row.permissions" :key="p.id">{{p.name}}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="s"><el-button link type="primary" @click="open(s.row)">编辑</el-button><el-button link type="danger" @click="remove(s.row.id)">删除</el-button></template></el-table-column></el-table><el-dialog v-model="visible" :title="form.id?'编辑角色':'新增角色'"><el-form label-width="80px"><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="说明"><el-input v-model="form.description"/></el-form-item><el-form-item label="权限"><el-checkbox-group v-model="form.permission_ids"><el-checkbox v-for="p in permissions" :key="p.id" :value="p.id">{{p.name}}</el-checkbox></el-checkbox-group></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{ElMessageBox}from'element-plus';import{createRole,deleteRole,getPermissions,getRoles,updateRole}from'@/api';import type{Permission,Role}from'@/types';const items=ref<Role[]>([]),permissions=ref<Permission[]>([]),visible=ref(false),form=reactive({id:0,name:'',description:'',permission_ids:[] as number[]});async function load(){items.value=(await getRoles()).data;permissions.value=(await getPermissions()).data}function open(item?:Role){Object.assign(form,item?{id:item.id,name:item.name,description:item.description,permission_ids:item.permissions.map(p=>p.id)}:{id:0,name:'',description:'',permission_ids:[]});visible.value=true}async function save(){const data={name:form.name,description:form.description,permission_ids:form.permission_ids};if(form.id){await updateRole(form.id,data)}else{await createRole(data)}visible.value=false;await load()}async function remove(id:number){await ElMessageBox.confirm('确认删除该角色？');await deleteRole(id);await load()}onMounted(load);</script>
